mkdir -p /tmp/claude-1000/-home-sfmqrb-git-rishe/b3fc9033-a4ae-4052-ab02-8a5f609ee6da/scratchpad && cat > /tmp/claude-1000/-home-sfmqrb-git-rishe/b3fc9033-a4ae-4052-ab02-8a5f609ee6da/scratchpad/build158.py <<'PYEOF'
# -*- coding: utf-8 -*-
import json, io

W_ETYM_EUROPE = "https://www.etymonline.com/word/Europe"
W_ETYM_MOROCCO = "https://www.etymonline.com/word/Morocco"
W_WP_EUROPE = "https://en.wikipedia.org/wiki/Europe"
W_WP_MARRAKESH = "https://en.wikipedia.org/wiki/Marrakesh"
W_WT_VALA = "https://en.wiktionary.org/wiki/%D9%88%D8%A7%D9%84%D8%A7"
W_WT_ORTHOS = "https://en.wiktionary.org/wiki/%E1%BD%80%CF%81%CE%B8%CF%8C%CF%82"
W_WT_GHARB = "https://en.wiktionary.org/wiki/%D8%BA%D8%B1%D8%A8"
W_WT_MARRAKESH = "https://en.wiktionary.org/wiki/Marrakesh"
W_WT_EUROPA = "https://en.wiktionary.org/wiki/Europa"

doc = {
  "pdf_page": 158,
  "book_page": 128,
  "verified_by": "claude-opus-5",
  "verified_on": "2026-09-05",
  "entries": [
    {
      "entry": 0,
      "root": "Erěbu",
      "verdict": "plausible",
      "modern_form": "Akkadian erēbu 'to enter, go in; (of the sun) to go down, set' (ereb šamši 'sunset, west'); ultimately Proto-Semitic *ġrb 'to enter, to set (of the sun)'",
      "note": "The Akkadian headword, its language label and its gloss are all correct: erēbu is the ordinary Akkadian verb 'to enter', used of the sun setting, whence ereb šamši 'sunset, the West'. Two structural reservations. (a) The chart makes Arabic ġ-r-b and Hebrew ʿerebh DESCEND from Akkadian; modern Semitists treat all three as sister reflexes of one Proto-Semitic root *ġrb (Akkadian lost the gutturals, so *ġarābu > erēbu; Hebrew merged *ġ into ʿ, so *ġereb > ʿereb; Arabic alone keeps ġ). Nourai's own source Zimmern (AKD 64) writes the borrowing arrow with 'viell.' ('perhaps'), and Klein s.v. maarib says only 'is rel. to'. (b) The point of the whole chart — Greek Eurṓpē from this Semitic word — is rejected by current scholarship (M. L. West: 'phonologically the match is very poor'; Beekes: Pre-Greek). REFERENCE MISPRINT IN THE BOOK (not an extraction error): the Arabic node #1 is cited as 'AKD:640,854', but Zimmern's Akkadische Fremdwörter has only ~85 printed pages. The printed page (checked at 600 dpi) really does read AKD:640,854; it is Nourai's misprint, almost certainly for AHD:640,854, i.e. the American Heritage Dictionary pages he cites twice more on this same chart (AHD:854 Morocco, AHD:452 Europe). The JSON reproduces the page faithfully.",
      "note_fa": "ریشهٔ اکدی erēbu «درآمدن، وارد شدن؛ فرو رفتن (خورشید)» واژه‌ای واقعی و برچسب زبانی و معنای آن درست است؛ ترکیب ereb šamši در اکدی یعنی «غروب آفتاب، باختر». اما دو ایراد ساختاری هست: نخست آنکه نورایی عربی «غ‌ر‌ب» و عبری ʿereb را زادهٔ اکدی نشان داده، حال آنکه زبان‌شناسان امروزی هر سه را بازتاب یک ریشهٔ سامی آغازین *ġrb می‌دانند (اکدی حروف حلقی را از دست داده و *ġarābu به erēbu بدل شده؛ عبری ġ را با ʿ یکی کرده؛ تنها عربی غین را نگاه داشته است)؛ خودِ تسیمرن (مأخذ AKD ص ۶۴) این وام‌گیری را با قید «شاید» آورده و کلاین هم فقط می‌گوید «هم‌ریشه است». دوم آنکه بنیادِ کل نمودار، یعنی گرفتن یونانی Eurṓpē از این واژهٔ سامی، در پژوهش امروزی رد شده است (وست و بیکس). همچنین ارجاع «AKD:640,854» در چاپ کتاب نادرست است — کتاب تسیمرن حدود ۸۵ صفحه بیشتر ندارد — و خطای چاپی خودِ نورایی است، نه خطای خوانش اسکن.",
      "sources": [W_ETYM_EUROPE, W_WP_EUROPE],
      "ref_check": [
        {"ref": "AKD:64", "status": "supports", "note": "Zimmern, Akkadische Fremdwörter, printed p. 64 (AKD.txt leaf 73, grep -n 'erebu'): 'akk. erēbu allg. eintreten, hineingehen (z. B. in ein Haus), dann spez. untergehen (von der Sonne und den Gestirnen), ereb šamši Sonnenuntergang, Westen : > viell. ... hebr. ʿāreb Abend, aram. ʿarab, arab. ġariba, äth. ʿarba untergehen (von der Sonne), hebr. maʿarab, aram. maʿrabā, arab. maġrab, maġrib, äth. maʿrāb Westen.' Exactly Nourai's root box and his Arabic/Hebrew arrows — but note Zimmern's own 'viell.' (perhaps)."},
        {"ref": "KLN:550", "status": "supports", "note": "Klein s.v. Europe (KLN_1966.txt leaf 299): 'L. Europa, fr. Gk. Eurṓpē ... which is prob. of Semitic origin. Cp. Akkad. erebu, \"to enter, go in; to go down, set\" (said of the sun), ereb shamshi, \"sunset\", Heb. ʿerebh, \"sunset, evening\" ... Accordingly Eurṓpē orig. meant \"the Region of the Setting Sun\".' The claim is Klein's, verbatim. (My leaf→page mapping puts this nearer p. 574 than p. 550, but the leaf-offset drifts in this scan; the entry itself is unambiguous.)"}
      ],
      "consulted": [
        {"src": "AKD", "where": "printed p. 64 (leaf 73)", "stance": "supports", "note": "'akk. erēbu ... ereb šamši Sonnenuntergang, Westen : > viell. ... arab. ġariba ... arab. maġrab, maġrib ... Westen' — Zimmern's own hedge 'viell.' is why I grade the root plausible rather than confirmed."},
        {"src": "KLN", "where": "s.v. Europe, Erebus, maarib (leaves 299, 292, 493)", "stance": "supports", "note": "s.v. maarib: Heb. ʿerebh 'which is rel. to Arab. gharaba, Ethiop. ʿaraba, \"(the sun) has set\", Arab. gharb, \"place of sunset, west\", Akkad. erebu, \"to enter, go in\", ereb shamshi, \"sunset\"' — 'rel. to', i.e. cognate, not descended."},
        {"src": "FSD", "where": "grep of vols 1-4 for 'erebu'", "stance": "silent", "note": "Funk & Wagnalls' Europe entry did not surface in the OCR; no independent statement found there."}
      ],
      "nodes": [
        {
          "id": 1, "lang": "Arabic", "words": "ğ.r.b; mağreb; Mağreb al aqsâ", "verdict": "plausible",
          "derivation": "Arabic ġ-r-b is a genuine triliteral root: ġaraba 'to depart, to withdraw; (of the sun) to set', whence ġarb 'sunset, west' and, with the ma- prefix of place/time, maġrib 'place and time of sunset; the West' (also the sunset prayer). Al-Maġrib al-Aqṣā 'the farthest West' is the standard term of the medieval Arab geographers (Ibn Ḥawqal, al-Idrīsī, al-Bakrī) for the westernmost of the three Maghribs (al-Adnā = Ifrīqiya, al-Awsaṭ = Algeria, al-Aqṣā = Morocco), so the gloss is right. The DERIVATION arrow, however, is not: Arabic did not borrow this root from Akkadian. Akkadian erēbu and Arabic ġaraba are parallel reflexes of Proto-Semitic *ġrb; Akkadian, which lost *ġ and *ʿ, shows e- where Arabic keeps ġ-, and the sound correspondence is regular in both directions, so nothing marks the Arabic as a loan. Zimmern, Nourai's source, prints the equation with 'viell.' (perhaps).",
          "derivation_fa": "ریشهٔ سه‌حرفی عربی «غ‌ر‌ب» اصیل است: غَرَبَ «دور شدن؛ فرو رفتن (خورشید)» و از آن غَرْب «باختر» و با پیشوند مکان/زمانِ مَـ، مَغْرِب «جای و هنگام غروب؛ باختر». ترکیب «المغرب الأقصی» اصطلاح جغرافی‌نویسان مسلمان (ابن حوقل، ادریسی، بکری) برای دورترین مغرب یعنی کشور مراکش است، پس معنایی که نورایی داده درست است. اما پیکانِ اشتقاق درست نیست: عربی این ریشه را از اکدی وام نگرفته؛ erēbu اکدی و غَرَبَ عربی هر دو بازماندهٔ سامی آغازین *ġrb اند و چون اکدی غین و عین را از دست داده، e- در برابر غ‌ـ عربی نشسته است. خودِ تسیمرن نیز این برابری را با قید «شاید» آورده است. حکم: با احتیاط پذیرفتنی است، ولی به‌عنوان هم‌ریشگی نه وام‌گیری.",
          "sources": [W_WT_GHARB, W_ETYM_MOROCCO],
          "ref_check": [
            {"ref": "AKD:640", "status": "not_found", "note": "Impossible page: Zimmern's Akkadische Fremdwörter runs to about 85 printed pages (111 scanned leaves). The printed chart really reads 'AKD:640,854' (verified on a 600-dpi render of pdf p. 158), so this is Nourai's own misprint — on internal evidence for AHD:640,854, since the same chart cites AHD:854 for Italian Marocco and English Morocco."},
            {"ref": "AKD:854", "status": "not_found", "note": "Same as above — out of range for AKD. The substance of the claim is however on AKD p. 64: 'ereb šamši Sonnenuntergang, Westen : > viell. ... arab. ġariba ... arab. maġrab, maġrib ... Westen'."}
          ],
          "consulted": [
            {"src": "AKD", "where": "printed p. 64 (leaf 73)", "stance": "partial", "note": "Zimmern lists exactly these Arabic forms (ġariba, maġrab/maġrib) beside Akkadian erēbu, but marks the borrowing 'viell.'"},
            {"src": "KLN", "where": "s.v. Maghrib (leaf 495)", "stance": "supports", "note": "'Maghrib, n., Barbary. — Arab. Maghrib, \"the West\", fr. gharaba, \"(the sun) has set\", whence gharb, \"place of the sunset, west\". See maarib.' — the internal Arabic morphology is exactly Nourai's."},
            {"src": "LKT", "where": "no. 674 (Ar. ġarbī)", "stance": "supports", "note": "Lokotsch: 'Aus demselben Stamme ar. ġaraba \"untergehen (Sonne)\" ist mit präfigiertem ma- zur Angabe des Ortes maġrib gebildet; der Maġreb ist Nordwestafrika von Tunis bis Marokko.'"}
          ]
        },
        {
          "id": 2, "lang": "Persian", "words": "ğarb «غرب»", "verdict": "confirmed",
          "derivation": "غرب ġarb, together with the chart's extras مغرب maġreb and غروب ġorūb, is a straightforward Arabic loanword taken into New Persian in the Islamic period; all three are ordinary Arabic derivatives of ġ-r-b (ġarb 'west', maġrib nomen loci/temporis, ġurūb the maṣdar 'setting of the sun'). Persian keeps the Arabic ġayn غ, which is why the borrowing is transparent — an inherited Iranian word could not begin with ġ. Mo'in flags the entry '[ع.]' (Arabic).",
          "derivation_fa": "«غرب» و واژه‌های افزودهٔ نمودار، «مغرب» و «غروب»، هر سه وام‌واژهٔ عربی‌اند که پس از اسلام وارد فارسی نو شده‌اند: غَرْب «باختر»، مَغْرِب اسم مکان و زمان، و غُروب مصدر «فروشدن خورشید». نگه داشتن حرف «غ» خود نشان وام‌بودن است، زیرا واژهٔ ایرانیِ اصیل با غ آغاز نمی‌شود. معین در فرهنگ فارسی این مدخل را با نشانِ «[ع.]» آورده است. ادعای نورایی درست است.",
          "sources": [W_WT_GHARB],
          "ref_check": [
            {"ref": "MON", "status": "supports", "note": "Mo'in, Farhang-e Farsi s.v. غرب (MON_part2.txt): 'غرب: [ع. غ.] (مصدر لازم) پنهان شدن، غایب گردیدن، ناپدید گشتن، دور شدن. (اِ.) جای فرو شدن آفتاب، مغرب؛ مقابل مشرق' — Arabic origin tag [ع.] and the sense 'place where the sun goes down, west'."}
          ],
          "consulted": [
            {"src": "MON", "where": "s.v. غرب and غروب (MON_part2.txt lines ~996, 1395)", "stance": "supports", "note": "غروب too is tagged '[ع.] (مصل.) فرو شدن' — Arabic infinitive 'to go down'."},
            {"src": "RCH", "where": "Richardson s.v. gharb", "stance": "supports", "note": "'gharb, Sun-set. The west. Africa. The flowing of tears ...' — the word is listed in a Persian-Arabic-English dictionary as an Arabism current in Persian."}
          ]
        },
        {
          "id": 3, "lang": "Italian", "words": "Marocco", "verdict": "disputed",
          "derivation": "Italian Marocco (Sp. Marruecos, Fr. Maroc, Ptg. Marrocos) really is the source of the European name of the country, but it does not come from Arabic maġrib / al-Maġrib al-Aqṣā. It comes from Marrākuš, the Almoravid capital founded in 1070, which from the 12th to the early 20th century gave its name to the whole kingdom ('the Kingdom of Marrakesh'). Phonetically maġrib could not yield Mar(r)occo — there is no route from ġ+b to rr+k. The name Marrākuš itself is Berber, not Arabic: the usual explanation is Tashelhit amur n akuš 'land of God' (Searight records an 11th-c. Qarawiyyin manuscript glossing it 'country of the sons of Kush'). Etymonline repeats Nourai's short-cut ('from Berber Marrakesh ... from Arabic Maghrib-al-Aqsa'), but that last step is a folk equation, not an accepted derivation.",
          "derivation_fa": "نام اروپاییِ کشور (ایتالیایی Marocco، اسپانیایی Marruecos، فرانسوی Maroc) در اصل از «مرّاکش» می‌آید، پایتخت مرابطون که در ۱۰۷۰ م. بنیاد شد و از سدهٔ دوازدهم تا آغاز سدهٔ بیستم نامش بر سراسر کشور نهاده می‌شد. از «مغرب» به‌هیچ‌روی نمی‌توان Marocco را گرفت؛ هیچ دگرگونی آواییِ شناخته‌ای غ و ب را به رّ و ک بدل نمی‌کند. خودِ «مرّاکش» هم واژه‌ای بربری است نه عربی: توضیح رایج آن amur n akuš در تاشلحیت به معنی «سرزمین خدا» است. پژوهش امروزی این پیکان نورایی (از ریشهٔ غ‌ر‌ب) را رد می‌کند و به جای آن نام شهر مرّاکش را می‌گذارد.",
          "sources": [W_ETYM_MOROCCO, W_WP_MARRAKESH],
          "ref_check": [
            {"ref": "AHD:854", "status": "not_checked", "note": "A page of the AHD New College Edition (1975/76) dictionary text, not of the Indo-European appendix; the only AHD on disk here is Watkins 1985 (IE roots only), which has no 'Morocco'. The New College scans on archive.org are lending-only."}
          ],
          "consulted": [
            {"src": "LKT", "where": "no. 1406 'Ar. Marākuš'", "stance": "contradicts", "note": "Lokotsch: 'Ar. Marākuš: Jetzt Marrākeš, die frühere südliche Hauptstadt Marokkos; hiernach wird das Ziegenleder genannt ... pg. marroquim, frz. maroquin ... engl. morocco.' He derives the European words from the CITY NAME and says nothing about maġrib."},
            {"src": "KLN", "where": "s.v. morocco, marocain (leaves 538, 511)", "stance": "contradicts", "note": "'morocco, n., a kind of fine flexible leather. — Named fr. Morocco, a city of NW. Africa' — Klein too anchors the name in the city, not in maġrib al-aqṣā."},
            {"src": "DEV", "where": "grep 'Maroc' in Devic", "stance": "silent", "note": "Devic mentions Maroc only in passing (s.vv. Argan, Filali, Mollah); he gives no etymology of the country name."}
          ]
        },
        {
          "id": 4, "lang": "Arabic", "words": "Marâkeš", "verdict": "disputed",
          "derivation": "The arrow is drawn backwards. Arabic مرّاكش Marrākuš is the ELDER form and the source of Italian Marocco, not a borrowing from it: the city was founded by the Almoravid Abū Bakr ibn ʿUmar in 462/1070 and appears in Arabic geographers from the 11th century, long before any Italian mercantile form. As Lokotsch (no. 1406) puts it, the Romance words marroquim / maroquin / morocco come 'hieraus', i.e. out of the Arabic name. Arabic itself took the name from Berber (amur n akuš 'land of God'), so Marrākuš is a Berberism in Arabic, not an Italianism. The word and its reference are real; only the direction of Nourai's arrow is wrong.",
          "derivation_fa": "جهت پیکان وارونه است. «مرّاكش» عربی صورت کهن‌تر و خاستگاه Marocco ایتالیایی است، نه وام‌گرفته از آن: شهر را ابوبکر بن عمرِ مرابطی در ۴۶۲ ق/۱۰۷۰ م. بنیاد نهاد و نامش از همان سدهٔ پنجم در جغرافی‌نویسان عرب آمده است، بسیار پیش از آنکه صورتی ایتالیایی در کار باشد. لوکوچ (شمارهٔ ۱۴۰۶) به‌روشنی می‌گوید واژه‌های رومی (marroquin، maroquin، morocco) «از این» نام عربی برآمده‌اند. عربی خود این نام را از بربری گرفته است. پس واژه درست است ولی سویهٔ اشتقاق در کتاب نادرست است.",
          "sources": [W_WP_MARRAKESH, W_WT_MARRAKESH],
          "ref_check": [
            {"ref": "None", "status": "not_checked", "note": "Nourai gives no reference for this node."}
          ],
          "consulted": [
